import { VueConstructor } from 'vue';
import { validateThemeOptions } from '@game-studio/operator-theme';
import SettingsMenuRoot from './components/settings-menu/root/index.vue';
import SettingsMenuGroup from './components/settings-menu/group/index.vue';
import SettingsMenuItem from './components/settings-menu/item/index.vue';
import SettingsMenuAccordion from './components/settings-menu/accordion/index.vue';
import SettingsMenuSection from './components/settings-menu/section/index.vue';
import SettingsItemInfo from './components/settings-item/info/index.vue';
import SettingsItemAction from './components/settings-item/action/index.vue';
import SettingsItemCheckbox from './components/settings-item/checkbox/index.vue';
import SettingsItemRadioButton from './components/settings-item/radio-button/index.vue';
import SettingsItemColourPicker from './components/settings-item/colour-picker/index.vue';
import SettingsItemSubMenu from './components/settings-item/sub-menu/index.vue';
import InputCheckbox from './components/input/checkbox/index.vue';
import InputColourPicker from './components/input/colour-picker/index.vue';
import { OPTIONS } from './options';
import { UserPreferences } from './user-preferences';
import { ISettingsPluginOptions } from './types';

export default {
    install(Vue: VueConstructor, options: ISettingsPluginOptions) {
        if (!options) {
            throw new Error('@game-studio/settings requires ISettingsPluginOptions to be provided');
        }

        if (!(typeof options.userId === 'number' || typeof options.userId === 'string')) {
            throw new Error('@game-studio/settings requires a valid "userId"');
        }

        if (typeof options.gameName !== 'string') {
            throw new Error('@game-studio/settings requires a valid "gameName"');
        }

        try {
            validateThemeOptions(options.theme);
        } catch (error: any) {
            throw new Error(`@game-studio/settings theme config invalid "${error.message}"`);
        }

        Vue.component('settings-menu-root', SettingsMenuRoot);
        Vue.component('settings-menu-group', SettingsMenuGroup);
        Vue.component('settings-menu-accordion', SettingsMenuAccordion);
        Vue.component('settings-menu-item', SettingsMenuItem);
        Vue.component('settings-menu-section', SettingsMenuSection);
        Vue.component('settings-item-info', SettingsItemInfo);
        Vue.component('settings-item-action', SettingsItemAction);
        Vue.component('settings-item-checkbox', SettingsItemCheckbox);
        Vue.component('settings-item-radio-button', SettingsItemRadioButton);
        Vue.component('settings-item-colour-picker', SettingsItemColourPicker);
        Vue.component('settings-item-sub-menu', SettingsItemSubMenu);
        Vue.component('input-checkbox', InputCheckbox);
        Vue.component('input-colour-picker', InputColourPicker);
        Object.assign(OPTIONS, options);
        UserPreferences.init(options.userId, options.gameName);
    }
};

export { UserPreferences };
export * from './sub-settings-manager';
export * from './event-emitter';
export * from './types';
